// Browser media loading with event handlers installed BEFORE src/load.
export function mediaKind(file){if(file.type?.startsWith('video/')||/\.(mp4|m4v|webm|mov|avi|mkv)$/i.test(file.name))return 'video';if(file.type?.startsWith('image/')||/\.(jpe?g|png|webp|gif|bmp|avif|heic|heif)$/i.test(file.name))return'image';throw Error('Нужны JPG, PNG, WebP или видео MP4/WebM.');}
export function waitVideo(video,url,timeoutMs=20000){return new Promise((resolve,reject)=>{let timer;const clear=()=>{clearTimeout(timer);video.removeEventListener('loadeddata',ready);video.removeEventListener('error',error);};const ready=()=>{if(video.readyState>=2&&video.videoWidth>0){clear();resolve();}};const error=()=>{clear();reject(Error('Браузер не декодирует это видео. Экспортируйте MP4 с кодеком H.264 или WebM.'));};video.addEventListener('loadeddata',ready);video.addEventListener('error',error);timer=setTimeout(()=>{clear();reject(Error('Видео не загрузилось за 20 секунд. Попробуйте MP4/H.264 меньшего размера.'));},timeoutMs);video.srcObject=null;video.src=url;video.load();ready();});}
export function fitSize(w,h,max=1920){if(!w||!h)throw Error('Файл не содержит читаемого кадра');const scale=Math.min(1,max/w,max/h);return [Math.max(1,Math.round(w*scale)),Math.max(1,Math.round(h*scale))];}
